 rows=dict(generated_at_utc=now(),stage=manifest['stage'],experiment_records=len(experiments),experiment_statuses=dict(statuses),experiments=experiments,intervention_record_rows=len(interventions),intervention_rows_by_type=dict(collections.Counter(x['type'] for x in interventions)),effective_confirmed_usage_limit_stops=len(effective_stops),effective_excluded_seconds=sum(s['excluded_seconds'] for s in effective_stops),api_record_rows=len(calls),unique_api_generation_calls=len(api),api=api,actual_api_cost_usd=sum(r['cost_usd'] or 0 for r in api),api_failed_unique_calls=sum(r['status'] in ['failed','error','cancelled'] for r in api),api_budget_usd=manifest['conditions']['api_budget_usd'],session_usage_and_cost=None,session_ids=dict(initial=manifest.get('session_id'),continuations=manifest.get('continuation_session_ids')),unknowns=manifest['unknowns'])
